  const [root, home, git, diff, usage, model] = await Promise.all([
    $.session.root(),
    $.env.get('HOME'),
    $.process.run(['git', 'branch', '--show-current']).catch(() => ({ exitCode: 1, stdout: '', stderr: '' })),
    $.process.run(['git', 'diff', '--shortstat', 'HEAD']).catch(() => ({ exitCode: 1, stdout: '', stderr: '' })),
